"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[6131],{46131:a=>{a.exports=JSON.parse('{"slug":"nobel-ekonomika-2026-holl-vudford-ozhidaniya","locale":"ru","title":"Нобелевскую премию по экономике дали за модели, которыми центробанки учитывают ожидания людей","description":"Нобелевку по экономике 2026 года получили Холл и Вудфорд. Их модели помогают понять, почему ставка Банка России 14% держится при инфляции 7,17%.","blocks":[{"id":"b001","kind":"paragraph","text":"Нобелевский комитет 12 октября 2026 года присудил премию по экономике Роберту Холлу из Стэнфордского университета и Майклу Вудфорду из Колумбийского университета. Формулировка — \xabза микроэкономические основы макроэкономической стабилизации\xbb. Лауреаты разделят 12 млн шведских крон, около $1,2 млн. По словам комитета, модели, выросшие из их работ, сейчас используют центральные банки и министерства финансов по всему миру."},{"id":"b002","kind":"paragraph","text":"Стабилизация — это то, чем занимаются центробанк и правительство: тормозят экономику, когда она перегревается и цены растут, и разгоняют, когда растёт безработица. Почти 100 лет назад Джон Мейнард Кейнс предложил считать это через связи между большими цифрами: инфляцией, безработицей, потреблением. В 1970-е эти связи сломались. США пытались снизить безработицу, разгоняя спрос, а получили одновременно и безработицу, и высокую инфляцию."},{"id":"b003","kind":"paragraph","text":"Холл и Вудфорд построили модели снизу, из решений отдельных людей и фирм. Холл в работе 1978 года, развивая идеи Милтона Фридмана, показал, что люди тратят исходя из того, какой доход ждут в будущем, а не только из сегодняшней зарплаты. Отсюда главный вывод: экономика реагирует не только на то, что происходит, но и на то, чего люди ждут. И центробанк, объясняя свои планы, может менять эти ожидания."},{"id":"b004","kind":"paragraph","text":"Как ожидания двигают цены, проще всего увидеть на арендодателе. Если он ждёт, что за год всё подорожает на 14%, он поднимает аренду сразу, а не через год. Арендатор, который тоже ждёт подорожания, поднимает цены на свои услуги. В итоге цены растут, потому что их роста ждут. Такие ожидания называют инфляционными."},{"id":"b005","kind":"paragraph","text":"В России этот разрыв сейчас большой. Годовая инфляция, по оценке Минэкономразвития на 5 октября, 7,17%, а население, по опросу Банка России, в сентябре ждало на год вперёд 14,2%. Банк России каждый месяц публикует этот опрос и следит за ним при решениях по ставке. Пока люди ждут роста цен почти в 2 раза быстрее, чем есть на самом деле, регулятор опасается, что разовые скачки цен, например из-за топлива, станут постоянными."},{"id":"b006","kind":"paragraph","text":"Для обычного человека из этой Нобелевки следует простая вещь: ставка Банка России зависит не только от сегодняшней инфляции, но и от того, во что верят люди. Пока ожидания высокие, кредиты остаются дорогими, а вклады доходными. Ждать с покупкой в кредит значит платить временем, брать сейчас значит платить высоким процентом. Решение по ставке Банк России объявит 23 октября, и на ожидания населения в нём будут смотреть так же внимательно, как на сами цены."},{"id":"b007","kind":"heading","text":"Кто получил Нобелевскую премию по экономике в 2026 году?"},{"id":"b008","kind":"paragraph","text":"Американские экономисты Роберт Холл из Стэнфорда и Майкл Вудфорд из Колумбийского университета. Премию 12 октября 2026 года присудили \xabза микроэкономические основы макроэкономической стабилизации\xbb, они разделят 12 млн шведских крон."},{"id":"b009","kind":"heading","text":"За что дали Нобелевскую премию по экономике 2026 года?"},{"id":"b010","kind":"paragraph","text":"За модели, в которых экономика складывается из решений отдельных людей и фирм, а эти решения зависят от ожиданий будущего. На таких моделях центральные банки и министерства финансов решают, когда тормозить и когда разгонять экономику."},{"id":"b011","kind":"heading","text":"Как Нобелевская премия связана со ставкой Банка России?"},{"id":"b012","kind":"paragraph","text":"Модели лауреатов объясняют, почему ожидания двигают цены. Годовая инфляция в России 7,17%, а население ждёт 14,2%. Пока ожидания высокие, разовый скачок цен может стать постоянным, поэтому Банк России не спешит снижать ставку 14%."}],"sources":[{"label":"Nobel prize in economics awarded to Robert E. Hall and Michael Woodford","url":"https://www.cnbc.com/2026/10/12/nobel-economics-prize-winner-woodford-hall.html"},{"label":"Кто и за что получил Нобелевскую премию по экономике","url":"https://www.vedomosti.ru/economics/articles/2026/10/13/1236487-kto-poluchil-nobelevskuyu-premiyu-po-ekonomike"},{"label":"Триумф новокейнсианства. За что дали Нобеля по экономике в этом году?","url":"https://thebell.io/triumf-novokeynsianstva-za-chto-dali-nobelya-po-ekonomike-v-etom-godu"},{"label":"Инфляционные ожидания и потребительские настроения, сентябрь 2026","url":"https://www.cbr.ru/analytics/dkp/inflationary_expectations/Infl_exp_26-09/"},{"label":"Инфляция в России с 29 сентября по 5 октября","url":"https://www.vedomosti.ru/economics/news/2026/10/07/1235202-inflyatsiya-v-rossii"}],"sourceBodySha256":"e13ad2b2a2ae1a90ea84da9b64778750943d70fe565916eb1fb9a1a889724ba6"}')}}]);